package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var orderFile *os.File
var scanner *bufio.Scanner
var inputDone bool

func enforceDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// Truncate to scale first (toward zero)
	val = val.Truncate(int64(scale))
	// keep low-order integer digits
	pow10 := decimal.NewFromInt(1)
	for i := 0; i < intDigits; i++ {
		pow10 = pow10.Mul(decimal.NewFromInt(10))
	}
	// integer part
	intPart := val.Truncate(0)
	frac := val.Sub(intPart)
	// handle negative
	neg := intPart.IsNegative()
	if neg {
		intPart = intPart.Neg()
	}
	// mod
	modInt := intPart.Mod(pow10)
	if neg {
		modInt = modInt.Neg()
	}
	return modInt.Add(frac)
}

func enforceInt2(v int64) int64 {
	v = v % 100
	if v < 0 {
		v += 100
	}
	return v
}

func formatEdited(val decimal.Decimal, pic string) string {
	// split picture
	var intPic, decPic string
	if idx := strings.Index(pic, "."); idx >= 0 {
		intPic = pic[:idx]
		decPic = pic[idx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	// prepare integer and decimal strings from val
	// use absolute value for formatting (no sign needed)
	absVal := val.Abs()
	scale := 0
	if decPic != "" {
		scale = len(decPic)
	}
	// get string fixed with scale
	var fixed string
	if scale > 0 {
		fixed = absVal.StringFixed(int32(scale))
	} else {
		fixed = absVal.Truncate(0).StringFixed(0)
	}
	var intStr, decStr string
	if scale > 0 {
		parts := strings.SplitN(fixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			decStr = parts[1]
		} else {
			decStr = strings.Repeat("0", scale)
		}
		// ensure decStr length == scale (StringFixed guarantees)
		if len(decStr) < scale {
			decStr = decStr + strings.Repeat("0", scale-len(decStr))
		} else if len(decStr) > scale {
			decStr = decStr[:scale]
		}
	} else {
		// no decimal part
		// intStr is fixed (may contain sign? abs ensures no)
		intStr = fixed
		// remove any dot
		if idx := strings.Index(intStr, "."); idx >= 0 {
			intStr = intStr[:idx]
		}
	}

	// count digit slots in intPic
	digitSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			digitSlots++
		}
	}
	// build integer digits string of length digitSlots
	// intStr may be longer than digitSlots => keep low-order digits
	var digitsForSlots string
	if len(intStr) > digitSlots {
		digitsForSlots = intStr[len(intStr)-digitSlots:]
	} else if len(intStr) < digitSlots {
		digitsForSlots = strings.Repeat("0", digitSlots-len(intStr)) + intStr
	} else {
		digitsForSlots = intStr
	}

	// map digits to picture
	intPicRunes := []rune(intPic)
	resultRunes := make([]rune, len(intPicRunes))
	copy(resultRunes, intPicRunes)
	// indices of digit positions
	digitPos := []int{}
	for i, ch := range intPicRunes {
		if ch == 'Z' || ch == '9' {
			digitPos = append(digitPos, i)
		}
	}
	for k, pos := range digitPos {
		resultRunes[pos] = rune(digitsForSlots[k])
	}

	// zero suppression for Z
	foundNonZero := false
	for _, pos := range digitPos {
		picCh := intPicRunes[pos]
		dig := resultRunes[pos]
		if picCh == 'Z' && dig == '0' && !foundNonZero {
			resultRunes[pos] = ' '
		} else {
			// not suppressed
			if dig != ' ' && dig != ',' {
				// if this is a non-zero digit, mark found
				// also a '9' with zero should count as found (we are printing it)
				// So any non-space digit that is not suppressed marks
				if dig != '0' {
					foundNonZero = true
				} else {
					// dig == '0' but picCh == '9' (or Z with earlier non-zero)
					// This zero is printed, so suppression ends
					if picCh == '9' {
						foundNonZero = true
					} else {
						// Z with zero but after foundNonZero already true, it is printed as 0
						if foundNonZero {
							// keep as 0, found stays true
						} else {
							// This case is Z with zero but we decided not to suppress because
							// foundNonZero was already true (should not happen for leading)
							// Keep 0 and set found
							foundNonZero = true
						}
					}
				}
				// If we printed anything (including zero at a 9), we consider found for purpose of commas
				// For Z with non-zero, already set
				if resultRunes[pos] != ' ' {
					// we need to ensure future commas know we have a printed digit
					// foundNonZero already reflects
					// For Z where digit !=0 we set above; for 9 where digit==0 we set
				}
			}
			if resultRunes[pos] != ' ' {
				// At least one digit has been printed; ensure found is true if we printed a 9 zero
				// Actually for Z non-zero we already true
				// Keep true
				if !foundNonZero {
					// This can happen if we printed a Z zero after a non-zero? but then foundNonZero already true
					// So nothing
				}
			}
		}
	}
	// Fix found logic for commas: simpler second pass to decide comma visibility
	// Find first non-space digit index in resultRunes
	firstDigitIdx := -1
	for i, r := range resultRunes {
		if r >= '0' && r <= '9' {
			firstDigitIdx = i
			break
		}
	}
	if firstDigitIdx >= 0 {
		for i, ch := range intPicRunes {
			if ch == ',' {
				if i < firstDigitIdx {
					resultRunes[i] = ' '
				} else {
					resultRunes[i] = ','
				}
			}
		}
	} else {
		// all spaces (should not happen because 9 ensures at least one digit, but if digitSlots 0)
		for i, ch := range intPicRunes {
			if ch == ',' {
				resultRunes[i] = ' '
			}
		}
	}

	formattedInt := string(resultRunes)
	if decPic != "" {
		return formattedInt + "." + decStr
	}
	return formattedInt
}

func formatPIC99(v int64) string {
	v = enforceInt2(v)
	if v < 0 {
		v = -v
		v = v % 100
	}
	return fmt.Sprintf("%02d", v)
}

func mainPara() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		if os.IsNotExist(err) {
			inputDone = true
			WsEofFlag = "Y"
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner = bufio.NewScanner(orderFile)
		// allow large lines
		// default split is ScanLines
		readPara()
		for !inputDone {
			processPara()
		}
		orderFile.Close()
	}
	summaryPara()
}

func readPara() {
	if scanner == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if !scanner.Scan() {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line := scanner.Text()
	// COBOL LINE SEQUENTIAL: pad with spaces on right if shorter
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse fields
	orderRec.OrId = line[0:5]
	orderRec.OrStat = line[5:6]
	qtyStr := line[6:9]
	qtyStrTrim := strings.TrimSpace(qtyStr)
	if qtyStrTrim == "" {
		orderRec.OrQty = 0
	} else {
		var q int64
		fmt.Sscan(qtyStrTrim, &q)
		orderRec.OrQty = q
	}
	priceStr := line[9:15]
	priceStrTrim := strings.TrimSpace(priceStr)
	if priceStrTrim == "" {
		priceStrTrim = "0"
	}
	// price is digits only, implied V99
	// parse as integer
	var pInt int64
	fmt.Sscan(priceStrTrim, &pInt)
	orderRec.OrPrice = decimal.New(pInt, -2)
}

func processPara() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if orderRec.OrQty == 0 {
		WsBadQty = enforceInt2(WsBadQty + 1)
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		qtyDec := decimal.NewFromInt(orderRec.OrQty)
		raw := qtyDec.Mul(orderRec.OrPrice)
		// truncate to scale 2
		raw = raw.Truncate(2)
		WsTotal = enforceDecimal(raw, 8, 2)
		WsNewCount = enforceInt2(WsNewCount + 1)
		showPara()
	} else if orderRec.OrStat == "S" {
		qtyDec := decimal.NewFromInt(orderRec.OrQty)
		raw := qtyDec.Mul(orderRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// ROUNDED to scale 2
		raw = raw.Round(2)
		WsTotal = enforceDecimal(raw, 8, 2)
		WsShipCount = enforceInt2(WsShipCount + 1)
		showPara()
	} else if orderRec.OrStat == "C" {
		WsCancelCount = enforceInt2(WsCancelCount + 1)
		showPara()
	} else {
		WsInvalid = enforceInt2(WsInvalid + 1)
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = enforceDecimal(WsGrand, 10, 2)
	readPara()
}

func showPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func summaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", formatPIC99(WsNewCount), formatPIC99(WsShipCount), formatPIC99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", formatPIC99(WsInvalid), formatPIC99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	mainPara()
}

